# Hypothesis: a generic TypeIs guard narrows a union-typed attribute in both branches, so checkers should reveal float in the positive branch and int | str in the negative one, and the negative branch must not keep float.
from dataclasses import dataclass
from typing import TypeIs, reveal_type


def is_instance_of[T](x: object, kind: type[T]) -> TypeIs[T]:
    return isinstance(x, kind)


@dataclass
class Box:
    value: int | str | float


def scale(box: Box) -> float:
    if is_instance_of(box.value, float):
        reveal_type(box.value)
        return box.value * 2
    reveal_type(box.value)
    if isinstance(box.value, int):
        return box.value * 2.0
    return float(len(box.value))


def first(items: list[int | None]) -> int:
    if items[0] is not None:
        reveal_type(items[0])
        return items[0]
    return -1


assert scale(Box(2.5)) == 5.0
assert scale(Box(3)) == 6.0
assert scale(Box("abc")) == 3.0
assert first([None]) == -1
assert first([7]) == 7
